export class RuleError extends Error{constructor(message,code='VALIDATION'){super(message);this.code=code;}}
export function ensure(condition,message,code){if(!condition)throw new RuleError(message,code);}
export const text=v=>String(v??'').trim();
export const key=v=>text(v).toUpperCase().replace(/\s+/g,' ');
export const clone=v=>structuredClone(v);
// Stable display serials are independent of supplier-facing PO numbers and revisions.
export function ensureOrderSerials(state){
 const used=new Set();let next=Number.isSafeInteger(state.nextOrderSerial)&&state.nextOrderSerial>0?state.nextOrderSerial:1,changed=false;
 for(const o of state.orders){if(o.serialNumber==null)continue;ensure(Number.isSafeInteger(o.serialNumber)&&o.serialNumber>0&&!used.has(o.serialNumber),'Order serials must be unique positive integers.');used.add(o.serialNumber);next=Math.max(next,o.serialNumber+1);}
 const missing=state.orders.map((o,index)=>({o,index})).filter(({o})=>o.serialNumber==null).sort((a,b)=>String(a.o.createdAt||'').localeCompare(String(b.o.createdAt||''))||a.index-b.index);
 for(const {o} of missing){ensure(Number.isSafeInteger(next)&&next<Number.MAX_SAFE_INTEGER,'Order serial limit reached.');o.serialNumber=next++;changed=true;}
 if(state.nextOrderSerial!==next){state.nextOrderSerial=next;changed=true;}return changed;
}
export const isoDay=(v=new Date())=>new Date(v).toISOString().slice(0,10);
export function dateValid(v){return /^\d{4}-\d{2}-\d{2}$/.test(text(v))&&!isNaN(Date.parse(v))&&isoDay(v)===v;}
export function dateRequired(v,label='Date'){ensure(dateValid(v),label+' must be a valid YYYY-MM-DD date.');return v;}
export function addDays(v,n){dateRequired(v.slice(0,10));const d=new Date(v.slice(0,10)+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10);}
export const daysBetween=(a,b)=>Math.round((Date.parse(b+'T12:00:00Z')-Date.parse(a+'T12:00:00Z'))/86400000);
export function integer(v,label,min=1,max=10000000){const n=Number(v);ensure(Number.isSafeInteger(n)&&n>=min&&n<=max,`${label} must be a whole number from ${min} to ${max}.`);return n;}
export function toMinor(v){const s=text(v);ensure(/^\d+(\.\d{1,2})?$/.test(s),'Amount must be non-negative, with at most two decimals.');const[a,b='']=s.split('.');const n=Number(BigInt(a)*100n+BigInt(b.padEnd(2,'0')));ensure(Number.isSafeInteger(n)&&n<=1e12,'Amount exceeds the supported limit.');return n;}
export function toRate(v){const s=text(v);ensure(/^\d+(\.\d{1,6})?$/.test(s),'Exchange rate must have at most six decimals.');const[a,b='']=s.split('.');const n=Number(BigInt(a)*1000000n+BigInt(b.padEnd(6,'0')));ensure(n>0&&Number.isSafeInteger(n),'Exchange rate must be positive.');return n;}
export function convertMinor(amount,rate){const n=Number((BigInt(amount)*BigInt(rate)+500000n)/1000000n);ensure(Number.isSafeInteger(n),'Converted amount is too large.');return n;}
export const major=n=>(Number(n||0)/100).toFixed(2);
export const formatMoney=(n,c='USD')=>new Intl.NumberFormat('en-IN',{style:'currency',currency:c,maximumFractionDigits:2}).format(Number(n||0)/100);
export const orderTotal=o=>o.lines.reduce((n,l)=>n+l.quantity*l.unitPriceMinor,0);
