// Approval actions have explicit roles; management/edit capabilities remain separate.
export const APPROVAL_ROLES=Object.freeze({FINALIZE_ARRIVAL_COSTING:'MANAGER',REOPEN_ARRIVAL_COSTING:'MANAGER',RETURN_ORDER:'MANAGER',APPROVE_ORDER:'MANAGER',APPROVE_AMENDMENT:'MANAGER',APPROVE_PI:'MANAGER',AUTHORIZE_PAYMENT:'MANAGER',VOID_PAYMENT:'MANAGER',APPROVE_ARTWORK:'PRODUCT_MANAGER',APPROVE_SPEC:'PRODUCT_MANAGER',REJECT_SPEC:'PRODUCT_MANAGER',APPROVE_BRAND_DELTA:'PRODUCT_MANAGER',APPROVE_BRAND_ARTWORK:'PRODUCT_MANAGER'});
