export const APPROVAL_STAGES=Object.freeze([
 ['APPROVE_ORDER','Purchase','PO approval and issue'],['RETURN_ORDER','Purchase','Return PO for correction'],['APPROVE_AMENDMENT','Purchase','PO amendment approval'],['APPROVE_PI','Purchase','Supplier PI approval'],
 ['FINALIZE_ARRIVAL_COSTING','Arrival costing','Finalize actual invoice costs'],['REOPEN_ARRIVAL_COSTING','Arrival costing','Reopen final costing for correction'],
 ['AUTHORIZE_PAYMENT','Payments','Payment milestone authorization'],['VOID_PAYMENT','Payments','Void payment record (correction only)'],
 ['APPROVE_ARTWORK','Artwork','Order artwork approval'],['APPROVE_SPEC','Product Lifecycle','Technical specification approval'],['REJECT_SPEC','Product Lifecycle','Technical specification rejection'],['APPROVE_BRAND_DELTA','Product Lifecycle','Brand-specific change approval'],['APPROVE_BRAND_ARTWORK','Product Lifecycle','Brand artwork approval'],
 ['APPROVE_PREPRODUCTION_SAMPLE','Production','Pre-production sample approval / rejection'],['COMPLETE_INITIAL_PAYMENT','Payments','Initial payment completion and automatic authorization']
].map(([command,group,label])=>Object.freeze({command,group,label,roles:Object.freeze(APPROVAL_ROLES[command]?[APPROVAL_ROLES[command]]:['MANAGER','EXECUTIVE']),assignedExecutiveOnly:['APPROVE_PREPRODUCTION_SAMPLE','COMPLETE_INITIAL_PAYMENT'].includes(command)})));
export function approvalRoles(state,command){const stage=APPROVAL_STAGES.find(s=>s.command===command);if(!stage)return [];const custom=state?.approvalControls?.stages;const roles=custom&&Object.hasOwn(custom,command)?custom[command]:stage.roles;return Array.isArray(roles)?roles.filter(r=>APPROVAL_ASSIGNABLE_ROLES.includes(r)):[];}
// An explicit Admin-saved preset, not a runtime override of later policy edits.
export function managerWorkflowStages(state){return Object.fromEntries(APPROVAL_STAGES.map(s=>[s.command,APPROVAL_ASSIGNABLE_ROLES.filter(r=>r==='MANAGER'||approvalRoles(state,s.command).includes(r))]));}
export function canPerformApproval(u,command,scope='LAE_IMPORT',now=null,state=null,o=null){
 const stage=APPROVAL_STAGES.find(s=>s.command===command);
 if(!stage||!u||u.active===false||!scopeAllowed(u,scope)||scope!=='LAE_IMPORT'||o?.deletedAt)return false;
 if(u.role==='ADMIN')return true;
 if(!approvalRoles(state,command).includes(u.role))return false;
 return !stage.assignedExecutiveOnly||u.role!=='EXECUTIVE'||!!o&&o.buyerId===u.id;
}
