export function productionReferenceDaysForOrderInput(state,p){const v=state.vendors.find(v=>v.id===p.vendorId);const lineRefs=(p.lines||[]).map(l=>state.items.find(i=>i.id===l.itemId)?.productionDays).filter(n=>Number.isFinite(Number(n))&&Number(n)>0).map(Number);return lineRefs.length?Math.max(...lineRefs):Number(v?.productionDays||30);}
export function currentApprovedPrice(state,vendorId,itemOrBaseId,currency,on=isoDay()){const c=key(currency);const item=state.items.find(i=>i.id===itemOrBaseId);const baseId=item?.baseId||itemOrBaseId;const valid=p=>p.vendorId===vendorId&&key(p.currency)===c&&p.status==='APPROVED'&&(!p.effectiveDate||p.effectiveDate<=on),latest=a=>a.sort((x,y)=>(String(x.effectiveDate||'')+'|'+String(x.at||'')).localeCompare(String(y.effectiveDate||'')+'|'+String(y.at||''))).at(-1)||null;if(item){const exact=(state.priceLists||[]).filter(p=>valid(p)&&p.itemId===item.id);if(exact.length)return latest(exact);}const base=(state.priceLists||[]).filter(p=>valid(p)&&p.baseId===baseId);if(base.length)return latest(base);const legacy=(state.priceLists||[]).filter(p=>valid(p)&&p.itemId&&state.items.find(i=>i.id===p.itemId)?.baseId===baseId);return latest(legacy);}
export function matchVendorCode(v,code){const c=key(code);return !!v&&(key(v.code)===c||key(v.fullReference)===c||key(v.fixedSupplierCode)===c||key(v.vendorSerial)===c||key((v.vendorSerial||'')+'-'+(v.fixedSupplierCode||''))===c);}
