function dLines(state,input,vendorId,ctx,currency,invoiceCurrency=currency,priceConversion=null){ensure(input?.length>0&&input.length<=100,'Add 1–100 order lines.');const seen=new Set(),lineIds=new Set();const lines=input.map(l=>{const i=state.items.find(i=>i.id===l.itemId),b=state.bases.find(b=>b.id===i?.baseId);ensure(i&&i.active&&b,'Select an active item with an explicit base product.');ensure(b.vendorId===vendorId,'All items must belong to the order’s linked supplier.');ensure(!seen.has(i.id),'A brand SKU can appear only once per PO.');seen.add(i.id);const quantity=integer(l.quantity,'Quantity'),unitPriceMinor=l.unitPriceMinor===undefined?toMinor(l.unitPrice):integer(l.unitPriceMinor,'Unit price',0,1e12);const pl=currentApprovedPrice(state,vendorId,b.id,currency,ctx.now.slice(0,10));const converted=pl?priceListInvoiceMinor(pl,{currency:invoiceCurrency,priceConversion}):null;ensure(!pl||converted!==null,'Enter the price-list exchange rate and date.');const lineId=l.id??ctx.id();ensure(typeof lineId==='string'&&/^[A-Za-z0-9_-]{1,120}$/.test(lineId),'Line ID must be a valid identifier.');ensure(!lineIds.has(lineId),'Order line IDs must be unique.');lineIds.add(lineId);return {id:lineId,itemId:i.id,code:i.code,erpItemCode:i.code,name:i.name,brand:i.brand,brandPrefix:i.brandPrefix||'',baseId:b.id,baseCode:b.code,baseItemCode:b.code,category:i.category,quantity,unitPriceMinor,specId:l.specId||null,artworkNotes:text(l.artworkNotes??i.artworkNotes),priceListSnapshot:pl?{entryId:pl.id,currency:pl.currency,unitPriceMinor:pl.unitPriceMinor,effectiveDate:pl.effectiveDate,revision:pl.revision||1,baseItemCode:b.code,...(priceConversion?{invoiceCurrency,invoiceUnitPriceMinor:converted,conversion:clone(priceConversion)}:{})}:null,priceOverride:!!pl&&unitPriceMinor!==converted};});ensure(Number.isSafeInteger(orderTotal({lines}))&&orderTotal({lines})<=1e12,'PO amount exceeds the supported limit.');return lines;}
