export function previewImport(state,rows){const norm=v=>key(v).replace(/[^A-Z0-9]/g,'');const aliases={VENDORCODE:'vendorCode',PRODUCTIONDAYS:'productionDays',ETADATE:'sourceEta',EARLIESTMONTH:'earliestMonth',ENGINE:'engine',FHCLASSIFICATION:'classification',ITEMCODE:'code',GRADE:'grade',PRODUCTCATEGORY:'category',PRODUCTCATAGORY:'category',ITEMNAME:'name',ITEMNAME1:'name',DESCRIPTION:'description'};const cats=new Map(state.categories.filter(c=>c.active).map(c=>[norm(c.name),c.name]));const count={};for(const r of rows){const h=Object.keys(r).find(h=>aliases[norm(h)]==='code'),c=key(r[h]);if(c)count[c]=(count[c]||0)+1;}return rows.map((raw,i)=>{const n={},errors=[],warnings=[];for(const[h,v]of Object.entries(raw)){const k=aliases[norm(h)];if(k)n[k]=text(v);}n.code=key(n.code);n.vendorCode=key(n.vendorCode);if(!n.code)errors.push('ITEM CODE is required');if(count[n.code]>1)errors.push('Duplicate ITEM CODE in this file');const matches=state.vendors.filter(v=>matchVendorCode(v,n.vendorCode)),exact=matches.find(v=>key(v.code)===n.vendorCode||key(v.fullReference)===n.vendorCode),vendor=exact||(matches.length===1?matches[0]:null);if(!exact&&matches.length>1)errors.push('Vendor code is ambiguous; use the full vendor reference');if(vendor&&(vendor.kind!=='SUPPLIER'||!vendor.scopes?.includes('LAE_IMPORT')))errors.push('Select an LAE Import product supplier');if(!vendor)errors.push('Vendor code is not mapped in VMS');else if(vendor.status!=='ACTIVE')errors.push('Vendor is not ACTIVE');if(!cats.has(norm(n.category)))errors.push('Unknown LAE product category');else n.category=cats.get(norm(n.category));if(!n.name)errors.push('ITEM NAME is required');if(n.productionDays&&(!/^\d+(\.0+)?$/.test(n.productionDays)||Number(n.productionDays)<=0))errors.push('Production days must be a positive whole number');n.productionDays=n.productionDays?Number(n.productionDays):null;if(n.earliestMonth&&!['January','February','March','April','May','June','July','August','September','October','November','December'].some(m=>key(m)===key(n.earliestMonth)))errors.push('Invalid earliest month');if(n.sourceEta){if(/^\d+(\.\d+)?$/.test(n.sourceEta)){const num=Number(n.sourceEta);if(num>=1&&num<100000)n.sourceEta=isoDay(new Date(Date.UTC(1899,11,30)+num*86400000));else errors.push('ETA serial date is outside supported range');}else if(!dateValid(n.sourceEta))errors.push('ETA must be YYYY-MM-DD or an Excel date');}const old=state.items.find(x=>key(x.code)===n.code);if(old&&old.scope!=='LAE_IMPORT')errors.push('Item belongs to another division');if(old?.baseId&&state.bases.find(b=>b.id===old.baseId)?.vendorId!==vendor?.id)errors.push('Supplier of an operational base cannot be changed by upload');if(!old?.baseId)warnings.push('Map base / brand and approve the specification before PO use');return {row:i+2,raw,normalized:n,result:errors.length?'REJECTED':old?'UPDATE':'CREATE',errors,warnings,before:old?clone(old):null};});}

export function previewMasterImport(state,rows,kind,user){
 const normalizedHeader=h=>key(h).replace(/[^A-Z0-9]/g,'');
 const fields=kind==='vendor'?['code','vendorSerial','fixedSupplierCode','name','kind','status','country','city','contact','email','phone','wechat','defaultExportPort','defaultPaymentMethod','defaultTerms','defaultPriceListCurrency','defaultBillingCurrency','productionDays','remarks']:['vendorCode','baseItemCode','currency','unitPrice','effectiveDate','reference','remarks'];
 const aliases=new Map(fields.map(f=>[normalizedHeader(f),f]));
 const parsed=rows.map((raw,index)=>{const values={},errors=[];for(const [h,v] of Object.entries(raw)){const f=aliases.get(normalizedHeader(h));if(f){if(Object.hasOwn(values,f))errors.push('Repeated heading: '+f);values[f]=text(v);}}
  if(!Object.values(raw).some(v=>text(v)))return null;
  const vendor=state.vendors.find(v=>key(v.code)===key(kind==='vendor'?values.code:values.vendorCode));
  const base=kind==='price'?state.bases.find(b=>key(b.code)===key(values.baseItemCode)):null;
  let payload,recordKey;
  if(kind==='vendor'){
   payload={...vendor,...values,id:vendor?.id||null};recordKey=key(values.code);
   for(const f of ['code','name','kind','status','defaultTerms','defaultPriceListCurrency','defaultBillingCurrency','defaultPaymentMethod','productionDays'])if(!text(payload[f]))errors.push(f+' is required');
   if(!['SUPPLIER','LOGISTICS'].includes(payload.kind))errors.push('kind must be SUPPLIER or LOGISTICS');
   if(payload.vendorSerial&&payload.fixedSupplierCode&&key(payload.code)!==key(payload.vendorSerial)+'-'+key(payload.fixedSupplierCode))errors.push('code must match vendorSerial-fixedSupplierCode');
  }else{
   payload={...values,vendorId:vendor?.id,baseId:base?.id};recordKey=[key(values.vendorCode),key(values.baseItemCode),key(values.currency)].join('|');
   if(!vendor)errors.push('Use the full vendor code from Vendor master');if(!base)errors.push('Base Item Code does not exist');
   for(const f of ['currency','unitPrice','effectiveDate'])if(!text(values[f]))errors.push(f+' is required');
  }
  if(!errors.length)try{let n=0;execute(state,{type:kind==='vendor'?'SAVE_VENDOR':'SAVE_PRICE_LIST',payload},user,{id:()=>`preview-${index}-${++n}`});}catch(e){errors.push(e.message);}
  return {row:index+2,raw,key:recordKey,payload,errors,result:errors.length?'REJECTED':kind==='vendor'?(vendor?'UPDATE':'CREATE'):'APPEND'};
 }).filter(Boolean);
 const counts=new Map();for(const r of parsed)counts.set(r.key,(counts.get(r.key)||0)+1);for(const r of parsed)if(counts.get(r.key)>1){r.errors.push('Repeated master key in this file; keep one row per key');r.result='REJECTED';}return parsed;
}

